// ------------------------------------------------------------------------------------------------ Config Studio (values only)

/**
 * Deliver new SETTINGS of an installed Cyrus mod: merge the changed values into the server's current config file
 * (comments, unknown keys and the owner's own edits to other keys stay), then apply as the settings declare: the mod's
 * reload command over the console (a failing reply rolls back and reloads the old file), a restart + health check, or
 * nothing (live). Same transaction as every delivery (journal, recover check, rollback). OFF unless CYRUS_DELIVERY=1
 * AND CYRUS_CONFIG_STUDIO=1. No jar, no pack, no model call.
 */
export async function deliverConfig(serverId: string, rel: ConfigRelease, host: DeliveryHost, opts: DeliverOptions = {}): Promise<DeliveryResult> {
  const env = host.env ?? process.env;
  const subject = { projectId: rel.projectId, revisionId: rel.revisionId };
  if (env[CONFIG_STUDIO_FLAG] !== "1") {
    const at = (host.now ?? (() => new Date()))().toISOString();
    return { ok: false, outcome: "refused", op: "config", serverId, subject, steps: [], notes: [], error: "the Config Studio is switched off (CYRUS_CONFIG_STUDIO is not 1); nothing was changed", startedAt: at, finishedAt: at };
  }
  return transaction({
    serverId, op: "config", subject, host, label: `config-${rel.projectId}`, opts,
    prepare: async (session, steps) => timed({ steps, host }, "preflight", async () => {
      if (!/^[A-Za-z0-9_-]{1,64}$/.test(rel.projectId)) throw new Refusal("preflight", "bad project id; nothing was changed");
      if (!/^[A-Za-z][A-Za-z0-9_]{1,39}$/.test(rel.pluginName)) throw new Refusal("preflight", "bad plugin name; nothing was changed");
      const v = validateConfigSpec(rel.spec);
      if (!v.ok) throw new Refusal("preflight", `the settings schema is invalid (${v.errors[0]?.message}); nothing was changed`);
      const spec = v.spec;
      const known = new Set(spec.params.map((p) => p.key));
      const bad = rel.changed.filter((k) => !known.has(k));
      if (bad.length) throw new Refusal("preflight", `${bad[0]} is not a setting of this mod; nothing was changed`);
      // WARN, DON'T BLOCK (owner rule 2026-10-12): out-of-range numbers ride along as warnings (lib/cyrus/delivery/config-check.ts)
      const chk = checkConfigValuesSoft(spec, Object.fromEntries(rel.changed.map((k) => [k, rel.values[k]])));
      if (!chk.ok) throw new Refusal("preflight", `${chk.errors[0].message}; nothing was changed`);
      // the mod must be installed (its plugin enabled on the last boot or its jar present)
      const ro = host.readOnly?.(session) ?? session.fs;
      const inv = await scanServer(ro, { base: session.base });
      const names = inv.plugins.map((p) => p.descriptor?.name?.toLowerCase()).filter(Boolean);
      if (!names.includes(rel.pluginName.toLowerCase())) throw new Refusal("preflight", `${rel.pluginName} is not installed on this server; nothing was changed`);
      const target = `${session.base}/plugins/${rel.pluginName}/${spec.file}`;
      const prev = readRecord(await session.fs.readFile(recordPath(rel.projectId), 1024 * 1024));
      return { body: (t: Txn) => { for (const w of chk.warnings.slice(0, 12)) t.notes.push(`warning: ${w.message}`); return configBody(t, rel, relaxLimits(spec, chk.outside), { ...rel.values, ...Object.fromEntries(rel.changed.map((k) => [k, chk.values[k]])) }, target, prev); } };
    }, () => "settings checked; the mod is installed"),
  });
}

async function configBody(t: Txn, rel: ConfigRelease, spec: ConfigSpec, values: ConfigValues, target: string, prev: DeliveryRecord | null): Promise<BodyOut> {
  const { jfs } = t;
  let changed = false, sha = "";
  await timed(t, "place", async () => {
    const cur = await jfs.readFile(target, 512 * 1024);
    const want = Object.fromEntries(rel.changed.map((k) => [k, values[k]]));
    let text: string;
    if (cur) {
      const w = writeValues(spec, cur.toString("utf8"), want);
      if (!w.ok) throw new Error(`the server's ${spec.file} could not be updated: ${w.errors[0].message}`);
      text = w.text;
    } else text = renderConfigYml(spec, values, [`${rel.pluginName} configuration (written by the Cyrus Config Studio).`]);
    const buf = Buffer.from(text, "utf8");
    sha = sha256(buf);
    if (cur && cur.equals(buf)) return `${spec.file} already has these values`;
    await jfs.mkdirp(target.slice(0, target.lastIndexOf("/")));
    await jfs.writeFile(`${target}.nxeon-part`, buf);
    await jfs.rename(`${target}.nxeon-part`, target);
    const back = await jfs.readFile(target, 512 * 1024);
    if (!back || sha256(back) !== sha) throw new Error(`${spec.file} does not verify after writing it`);
    changed = true;
    return `${spec.file}: ${rel.changed.length} setting(s) written`;
  }, (v) => v);
  let record: DeliveryRecord | null = prev;
  if (prev && changed) {
    record = { ...prev, config: { target, sha256: sha, revisionId: rel.revisionId, deliveredAt: (t.host.now ?? (() => new Date()))().toISOString() } };
    await timed(t, "record", async () => { const rp = recordPath(rel.projectId); await jfs.writeFile(`${rp}.part`, Buffer.from(JSON.stringify(record, null, 2) + "\n")); await jfs.rename(`${rp}.part`, rp); return rp; }, (v) => v);
  } else skip(t, "record", prev ? "nothing changed" : "the mod was not installed by Cyrus delivery: no delivery record to update");
  const applies = appliesFor(spec, rel.changed).applies;
  return {
    apply: { jarChanged: false, managedChanged: false, datapacks: [], modelsChanged: false, managedConfigChanged: false, loaderChanged: false, config: { changed, applies: applies === "none" ? "live" : applies, ...(spec.reload ? { reloadCommand: spec.reload.command } : {}) } },
    record, outcome: "updated", unchanged: !changed,
    expect: { plugins: [rel.pluginName], datapacks: [], worldgen: false },
  };
